{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret siger fejlagtigt, at arbejdsprøvning, særlig arbejdspladsindretning og arbejdsgiveroplysninger kan indgå. Kilden (3.4.1.3, l. 228-233) siger, at arbejdsprøvning og særlig arbejdspladsindretning ikke indgår, og at Udbetaling Danmark ikke kontakter arbejdsgivere. Det rammer rubrikken direkte: de to første led er ikke vurderingsled, og arbejdsgivere kontaktes ikke. Svaret siger heller ikke, at studierelevans, lokale forhold og erhvervsevne efter uddannelsen aldrig indgår. Det bruger 'Normalt nej' og 'Som udgangspunkt nej', hvilket svækker den klare udelukkelse. Påstanden om, at prognosen kan have betydning for varighed, er en korrekt tilføjelse (jf. bek. § 36, stk. 2)."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret dækker målestokken (erhvervsevne som uddannelsessøgende), at kommunens vurdering ikke er den samme, og at lokale forhold og erhvervsevne efter uddannelsen som udgangspunkt ikke indgår. Det mangler det kritiske element, at arbejdsprøvning og særlig arbejdspladsindretning ikke indgår, og at arbejdsgivere ikke kontaktes. Studierelevans og muligheden for at finde arbejde er kun delvist dækket, fordi svaret bruger 'normalt'."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler alle de syv led i spørgsmålet ét for ét og er direkte relevant, selv om indholdet er forkert på flere af dem."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledningsafsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det ikke kan vurderes, om kilden understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at kommunale vurderinger kan indgå som dokumentation, at arbejdsprøvning er et muligt bevis, at konkrete arbejdspladstilpasninger kan indgå, og at arbejdsgiveroplysninger kan være relevante. Disse regler er ikke støttet af materialet, og vejledningen siger direkte det modsatte. Kravet om ikke-bindende kommunal vurdering og SU-styrelsens egen vurdering er heller ikke støttet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret gør kildens klare udelukkelser til svage udgangspunkter med 'normalt nej' og 'som udgangspunkt nej'. Det fremhæver desuden ikke, at arbejdsprøvning, arbejdspladsindretning og arbejdsgiverkontakt ikke indgår. Svaret bevarer dog, at vurderingen angår erhvervsevne som uddannelsessøgende, og at prognosen kan have betydning for varigheden."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret siger, at vurderingen kun angår evnen til arbejde ved siden af uddannelsen og er SU-specifik. Samtidig lader det kommunale vurderinger, arbejdsprøvning og arbejdsgiveroplysninger indgå som bevis, uden at forklare hvordan det hænger sammen. Det er også uklart, hvordan 'nærmest ude af stand' som udgangspunkt forholder sig til kildens 'meget betydelige begrænsninger'."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Kilden bruger absolutte udelukkelser ('indgår ikke', 'kontakter heller ikke'), men svaret bruger 'kan indgå', 'kan være relevante', 'normalt nej' og 'som udgangspunkt nej'. Det gør udelukkelserne til skøn."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "partial",
      "reason": "Svaret dækker, at vurderingen angår erhvervsevne som uddannelsessøgende, og at lokale jobmuligheder og erhvervsevne efter uddannelsen som udgangspunkt ikke indgår. Det dækker ikke, at arbejdsprøvning, særlig arbejdspladsindretning og arbejdsgiverkontakt ikke indgår, og det svækker udelukkelsen af studierelevans. Det nævner heller ikke ordblind-eksemplet eller kravet om 'meget betydelige begrænsninger'."
    }
  },
  "overall_notes": "Svaret er velstruktureret og besvarer alle led, men fejler på kernepunktet. Det tillader arbejdsprøvning, særlig arbejdspladsindretning og arbejdsgiveroplysninger som mulige bevis, selv om vejledningen udelukker dem. Det blødgør de øvrige udelukkelser med 'normalt' og 'som udgangspunkt'. Svaret angiver ingen kilder."
}

